CREATE TABLE notification_preferences(user_id TEXT NOT NULL REFERENCES users(id),type TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),channel TEXT NOT NULL DEFAULT 'IN_APP',PRIMARY KEY(user_id,type));
CREATE TABLE notifications(notification_id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),type TEXT NOT NULL,priority TEXT NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,scheduled_at INTEGER NOT NULL,delivered_at INTEGER,read_at INTEGER,status TEXT NOT NULL CHECK(status IN('SCHEDULED','QUEUED','DELIVERED','READ','SNOOZED','CANCELLED','FAILED','EXPIRED')),channel TEXT NOT NULL DEFAULT 'IN_APP',source TEXT NOT NULL,related_entity TEXT NOT NULL,action_url TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,dedupe_key TEXT NOT NULL UNIQUE,audit_seq INTEGER REFERENCES audit_events(seq));
CREATE INDEX notifications_user ON notifications(user_id,scheduled_at DESC);
CREATE TABLE reminder_plans(id TEXT PRIMARY KEY,record_id TEXT NOT NULL UNIQUE REFERENCES records(id),patient_id TEXT NOT NULL REFERENCES patients(id),version INTEGER NOT NULL,config TEXT NOT NULL CHECK(json_valid(config)),active INTEGER NOT NULL CHECK(active IN(0,1)),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE reminder_versions(plan_id TEXT NOT NULL REFERENCES reminder_plans(id),version INTEGER NOT NULL,config TEXT NOT NULL CHECK(json_valid(config)),record_version INTEGER NOT NULL,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(plan_id,version));
CREATE TRIGGER reminder_version_no_update BEFORE UPDATE ON reminder_versions BEGIN SELECT RAISE(ABORT,'immutable reminder provenance'); END;
CREATE TRIGGER reminder_version_no_delete BEFORE DELETE ON reminder_versions BEGIN SELECT RAISE(ABORT,'immutable reminder provenance'); END;
CREATE TABLE medication_doses(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES reminder_plans(id),plan_version INTEGER NOT NULL,patient_id TEXT NOT NULL REFERENCES patients(id),record_id TEXT NOT NULL REFERENCES records(id),slot TEXT NOT NULL,scheduled_at INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('PENDING','TAKEN','TAKEN_LATE','SKIPPED','MISSED','CANCELLED')),acted_at INTEGER,snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),UNIQUE(plan_id,slot));
CREATE INDEX dose_patient_time ON medication_doses(patient_id,scheduled_at);
ALTER TABLE document_details ADD COLUMN language TEXT NOT NULL DEFAULT 'und';
ALTER TABLE document_details ADD COLUMN translation_status TEXT NOT NULL DEFAULT 'original';
ALTER TABLE patient_details ADD COLUMN timezone TEXT NOT NULL DEFAULT 'UTC';
